// HasSiteLogos applies the HasEdge predicate on the "site_logos" edge.
func HasSiteLogos() predicate.Asset {
	return predicate.Asset(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, SiteLogosTable, SiteLogosColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSiteLogosWith applies the HasEdge predicate on the "site_logos" edge with a given conditions (other predicates).
func HasSiteLogosWith(preds ...predicate.Site) predicate.Asset {
	return predicate.Asset(func(s *sql.Selector) {
		step := newSiteLogosStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

